import{_ as i,l as s,o as a,c as n,v as t,p as d,x as r,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"硬中断与软中断","description":"","frontmatter":{"title":"硬中断与软中断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hardirq-softirq.md","filePath":"cs/hardirq-softirq.md","lastUpdated":1789023840000}'),h={name:"cs/hardirq-softirq.md"};function E(A,e,_,u,f,m){const o=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="硬中断与软中断" tabindex="-1">硬中断与软中断 <a class="header-anchor" href="#硬中断与软中断" aria-label="Permalink to &quot;硬中断与软中断&quot;">​</a></h1><div class="epigraph"><p>硬中断上下文不能睡眠；软中断在开中断之后跑，仍不许睡眠，只是把可推迟的工作从 IRQ 线的关掩码下挪出来。</p><footer>—— 据 Bovet and Cesati, Understanding the Linux Kernel；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/interrupt-bottom-half">上一课</a>把设备 IRQ 拆成短上半与可推迟下半，但把 Linux 里「硬中断 / 软中断」两种<strong>上下文</strong>留白。缺口是：上半部对应硬 IRQ——可能关该线甚至关本地中断；下半部里有一类仍在中断返回前、以软中断形式跑，<strong>仍然不能睡眠</strong>，只是不再占用那条硬 IRQ 的关掩码。本课钉这两种上下文，不把 tasklet 队列写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若凡下半部都可以睡，网卡收包处理会去拿睡眠锁、去调页，硬中断延迟的上界就丢了。若凡下半部都关硬中断，其他设备会被一次协议处理饿死。缺口不是再讲<a href="/cs/exception-interrupt-entry">异常入口</a>，而是承认内核里至少两档：硬中断上下文（ISR）、软中断上下文（开硬中断、禁睡眠）。工作线程是第三档，下一课才请出来。</p><p><span class="marginnote">软中断按类型串行或分 CPU 串行，避免同一软中断在多核上重入同一全局结构。本课只要求「能推迟、仍不能睡」，不写编号表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬 IRQ：应答设备、清原因、把描述符链入队列、标记对应软中断 pending，尽快 <code>iret</code> 路径。返回用户或返回内核前，若 pending，关抢占、开硬中断，跑软中断：组包、提交套接字缓冲、<code>wakeup</code> 阻塞在<a href="/cs/syscall-path">系统调用路径</a>上的线程。软中断里禁止 <code>schedule</code> 进入睡眠。</p>',8)),(a(),d(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HW%5B%22%E7%A1%AC%20IRQ%22%5D%20--%3E%20ISR%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%E4%B8%8A%E4%B8%8B%E6%96%87%3A%20%E6%B8%85%E8%AE%BE%E5%A4%87%22%5D%0A%20%20ISR%20--%3E%20PEND%5B%22%E6%A0%87%E8%AE%B0%E8%BD%AF%E4%B8%AD%E6%96%AD%22%5D%0A%20%20PEND%20--%3E%20SOFT%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%E4%B8%8A%E4%B8%8B%E6%96%87%3A%20%E5%A4%84%E7%90%86%E3%80%81%E5%94%A4%E9%86%92%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与用户路径的会合点仍是等待队列：调用在路径里睡，软中断里唤醒。本课不写队列 API。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两档让延迟分层：硬中断延迟由 ISR 长度决定；软中断延迟还叠加在返回路径上，但其他硬 IRQ 可以插进来。共享数据因此要分清「与硬 IRQ 并发」还是「只与软中断并发」——锁与关中断的搭配是后课，本课只预告：硬 IRQ 里不能拿睡眠锁。</p><p><a href="/cs/io-dma">I/O 与 DMA</a> 仍只提供完成通知；本课不重讲总线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>BH</code> 历史名与 <code>softirq</code> 逐一对照成考古。NMI 几乎不能进这套推迟，后面单独一课。也不把用户信号当软中断：信号是进程的软件中断，对象不同。</p><p>后课默认：下半部里仍有不能睡的一档。更重、允许睡眠的推迟要交给专门机制，下一课讲 tasklet 与 workqueue。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬中断短、可关线；软中断可推迟但仍不能睡眠。</li><li>唤醒阻塞系统调用发生在软中断或更后的线程里。</li><li>可睡的推迟队列是下一课。</li><li>出处：Bovet and Cesati；Love, <em>LKD</em>。</li></ul>',9))])}const D=i(h,[["render",E]]);export{q as __pageData,D as default};
